const protocols={
 av:{name:'방실판 유입 · MV / TV inflow',purpose:'이완기 충만과 방실판 역류의 표적 평가',plane:'심첨 또는 기저부 4CV에서 각 방실판 유입과 빔을 나란히 맞춥니다.',gate:'승모판(MV)과 삼첨판(TV)을 각각 식별하고, 판륜 또는 그 바로 심실측에 PW 표본용적을 둡니다. 두 판막 신호를 섞지 않습니다.',settings:'유입 방향과 입사각을 작게(<20°) 맞추고 E/A가 분리되는 시간축을 사용합니다. 역류는 별도 컬러·스펙트럴 기록으로 확인합니다.',measure:'이완 초기 E파와 심방 수축 A파의 각 최고속도(cm/s)를 측정하고 E/A를 구합니다. 역류가 의심되면 발생 시기·지속시간·속도를 별도로 기록합니다.',pitfall:'E/A 융합, 태동, 부정맥에서는 비율의 신뢰도가 떨어집니다. 선택한 수축기·이완기 정지 화면만으로 측정할 수 없습니다.',images:['tv','mv'],refs:['echo','function'],early:'적응증이 있는 조기 정밀 심초음파에서 시행합니다. 중기 E/A 기준을 1분기에 대입하지 않습니다.'},
 lv:{name:'대동맥 유출 · Aortic VTI',purpose:'좌심실 유출 속도·박출량의 정밀 평가',plane:'LVOT 장축에서 대동맥판과 상행대동맥을 확인하고 유출 혈류에 정렬합니다.',gate:'대동맥판 수준에서 판막을 통과하는 전향성 혈류를 PW로 기록합니다. VTI와 판륜 계측은 같은 유출로·프로토콜을 사용합니다.',settings:'빔을 혈류와 평행하게 맞추고, 정렬을 각도 보정으로 대신하지 않습니다. 수축기 외곽선이 잘리지 않도록 scale/PRF와 baseline을 조절합니다.',measure:'한 수축기 유출 파형의 시작–끝 외곽선을 추적하여 VTI(cm)를 구합니다. PSV는 cm/s. 박출량(mL)=π×(판륜 직경[cm]/2)²×VTI[cm], 분당 박출량(mL/min)=박출량×FHR.',pitfall:'직경 오차가 면적 계산에서 제곱됩니다. 이완기 판륜 또는 다른 혈관의 VTI와 결합하지 않습니다. 이완기 View에서도 PW는 전체 심장 주기를 별도로 기록합니다.',images:['lv'],refs:['echo','function']},
 rv:{name:'폐동맥 유출 · Pulmonary VTI',purpose:'우심실 유출 속도·박출량의 정밀 평가',plane:'RVOT에서 폐동맥판과 주폐동맥을 확인하고 판막을 지나는 혈류에 정렬합니다.',gate:'폐동맥판 수준에서 전향성 유출 신호를 PW로 기록합니다. 원위 동맥관이나 폐동맥 분지의 신호와 구분합니다.',settings:'혈류와 빔을 평행하게 맞추고 수축기 파형 전체가 보이도록 PRF·baseline을 조절합니다. 각도 보정으로 부적절한 정렬을 대신하지 않습니다.',measure:'수축기 파형의 외곽선으로 VTI(cm), 최고점으로 PSV(cm/s)를 측정합니다. 수축기 폐동맥판륜 내경[cm]으로 면적을 구해 VTI와 FHR을 곱하면 우심실 박출량을 계산할 수 있습니다.',pitfall:'3VV의 MPA 직경은 폐동맥판륜 직경과 다릅니다. 좌·우심실 박출량을 혼동하지 않고 같은 검사에서 대응시킵니다.',images:['rv'],refs:['echo','function']},
 duct:{name:'동맥관 혈류 · Ductus arteriosus Doppler',purpose:'동맥관 협착·역방향 혈류가 의심될 때의 표적 평가',plane:'동맥관궁 종단면에서 MPA–동맥관–하행대동맥 경로를 추적합니다. 3VT 횡단면에서 필요 시 이 종단면으로 이동합니다.',gate:'동맥관 안에 PW gate를 두고 인접 대동맥이나 폐동맥판 유출이 섞이지 않도록 위치를 확인합니다.',settings:'혈류와 가능한 평행하게 정렬합니다. 높은 유속이 잘리지 않게 PRF·baseline을 조절하고 이완기 저속 신호도 보존합니다.',measure:'PSV·EDV(cm/s) 및 한 주기 전체 파형의 PI를 기록합니다. 컬러로 난류·흐름 방향을 함께 평가합니다.',pitfall:'한 속도값만으로 협착을 확정하지 않습니다. 입사각, 주수, 우심실 부담·삼첨판 역류와 함께 전문 평가합니다. 아래 사진은 경로를 보여 주는 컬러 예시입니다.',images:['duct'],refs:['echo']},
 arch:{name:'대동맥궁·협부 혈류 · Aortic arch / isthmus',purpose:'궁의 개방성과 전향성·역방향 혈류 평가',plane:'분지가 보이는 대동맥궁 장축면을 확보합니다. 3VV/3VT의 컬러 평가는 궁 장축면으로 보완합니다.',gate:'정밀 계측이 필요하면 좌쇄골하동맥 분지 이후, 동맥관 합류 이전의 협부를 확인해 PW gate를 놓습니다.',settings:'컬러 gain은 혈관 경계를 넘지 않게, PRF는 흐름을 놓치거나 aliasing이 생기지 않게 조정합니다. PW는 해당 혈류와 빔을 정렬합니다.',measure:'기본은 흐름 방향과 연결의 기록입니다. 협부 속도·파형 정량화는 해당 부위·주수의 전문 프로토콜에 따라 시행합니다.',pitfall:'컬러의 빨강·파랑은 탐촉자에 대한 방향이며 동맥·정맥 구분이 아닙니다. 모든 3VV에 별도의 필수 PI 계측이 있는 것은 아닙니다.',images:['arch'],refs:['echo']},
 ivc:{name:'대정맥·간정맥 파형 · Systemic venous Doppler',purpose:'정맥 환류와 심방 압력·충만 이상에 대한 정밀 평가',plane:'Bicaval View에서 SVC·IVC의 우심방 연결을 확인한 뒤 관심 정맥에 정렬합니다.',gate:'검사할 정맥을 이름으로 구분하여 gate를 혈관 안에 둡니다. IVC, 간정맥, DV가 합류하는 부위의 혼합 신호를 피합니다.',settings:'낮은 속도와 짧은 심방 수축 역류가 지워지지 않도록 wall filter와 시간축을 조정합니다.',measure:'수축기 S파, 이완기 전향파와 심방 수축 A파의 방향·속도·지속시간을 해당 정맥의 기준으로 기록합니다.',pitfall:'IVC의 짧은 A파 역류를 DV 역류와 동일하게 해석하지 않습니다. SVC·IVC·DV는 서로 대체할 수 없습니다.',images:['ivc'],refs:['echo','function']},
 ua:{name:'제대동맥 · Umbilical artery (UA)',purpose:'태반 혈관 저항과 태아 성장 제한의 적응증별 평가',plane:'제대 삽입부 횡단면을 확인한 뒤, 계측용으로 자유 제대 고리(Free loop)를 별도로 찾습니다.',gate:'컬러로 UA와 UV를 구별하고 한 제대동맥에 PW gate를 둡니다. 반복 검사에서는 표본 위치를 기록합니다.',settings:'이완기 혈류가 지워지지 않게 wall filter를 낮추고, 태동·호흡이 없는 구간에서 여러 일정한 주기를 확보합니다.',measure:'한 주기의 최대속도 외곽선을 추적해 PI=(PSV−EDV)/TAMX, RI=(PSV−EDV)/PSV, S/D=PSV/EDV를 구합니다. 이완기 혈류 소실·역류 여부도 기록합니다.',pitfall:'EDV=0이면 S/D를 유한값으로 계산하지 않습니다. 태아측·태반측·자유 고리는 저항이 다르므로 동일 위치 참고치를 사용합니다. 쌍태는 태아별 제대를 먼저 구분합니다.',images:['ua'],refs:['isuog'],early:'1분기 제대 형태·혈관 수 확인과 UA 저항 계측은 다릅니다. 아래 파형 계측은 중·후기 적응증 검사 참고이며 후기 기준을 초기 선별에 적용하지 않습니다.'},
 mca:{name:'중대뇌동맥 · Middle cerebral artery (MCA)',purpose:'빈혈 평가의 MCA-PSV 또는 혈류 재분포 평가의 MCA-PI',plane:'TTP에서 약간 꼬리쪽 두개저 축상면으로 이동하여 Willis환을 컬러로 찾습니다. 일반 BPD/HC 단면과는 다른 추가 단면입니다.',gate:'내경동맥에서 나오는 MCA의 근위 1/3에 PW gate를 둡니다.',settings:'입사각을 가능한 0°로 맞춥니다. 머리를 누르지 않고 태동이 없는 구간에서 적어도 3개, 10개 미만의 연속 파형을 기록합니다.',measure:'재현성 있는 최고점에서 PSV(cm/s), 주기 전체 외곽선에서 PI를 구합니다. PSV는 주수별 MoM, PI는 해당 참고치로 해석합니다. CPR=MCA-PI/UA-PI는 같은 평가에서 얻은 값으로 계산합니다.',pitfall:'원위 MCA는 PSV가 달라집니다. MCA-PSV와 MCA-PI의 검사 목적을 혼동하지 않고 CPR을 주수 무관 고정값으로 해석하지 않습니다.',images:['mca'],refs:['isuog'],early:'이 항목은 주로 중·후기 적응증 검사 참고입니다. 1분기 기본 두부 계측에 MCA-PSV·CPR을 일률적으로 추가하지 않습니다.'},
 dv:{name:'정맥관 · Ductus venosus (DV)',purpose:'적응증별 초기 선별 보조 또는 중·후기 정맥 혈역학 평가',plane:'상복부 정중시상 또는 적절한 사위 단면에서 UV–DV–IVC 연결을 컬러로 찾습니다. AC 단면을 그대로 사용하지 않습니다.',gate:'가늘고 빠른 유입부인 DV 협부에 작은 PW gate를 맞춰 UV·간정맥 신호를 제외합니다.',settings:'협부 흐름에 빔을 정렬하고 a-wave를 식별할 만큼 시간축을 넓힙니다. 낮은 속도를 지우거나 기저선 잡음이 a-wave를 덮지 않도록 filter를 조절합니다.',measure:'수축기 S, 이완기 D, 심방 수축 a-wave를 식별합니다. a-wave의 전향·소실·역류와 정맥 박동지수 PIV=(S−a)/TAMX를 해당 주수 기준으로 기록합니다.',pitfall:'IVC의 정상 심방 수축 역류가 섞이면 DV a-wave를 오판할 수 있습니다. 기저선 주변 잡음을 조절한 뒤 반복 확인합니다.',images:['dv'],refs:['isuog','first'],early:'11–13+6주에는 훈련된 검사자가 적응증·선별 프로토콜에 따라 평가합니다. 아래 영상의 정확한 주수는 확인되지 않아 초기 정상값 예시로 사용하지 않습니다.'},
 uta:{name:'자궁동맥 · Uterine artery (UtA)',purpose:'산모 측 태반 관류·전자간증 위험 평가의 적응증별 검사',plane:'태반 자체의 혈관이 아니라 산모 자궁동맥을 별도 단면에서 찾습니다.',gate:'좌우 자궁동맥을 각각 기록합니다. 1분기 경복부는 경부 주위에서 자궁체부 방향으로 상승하는 혈관을 찾아 궁상동맥 분지 전에서 측정합니다. 2·3분기 경복부는 외장골동맥과 교차한 뒤 약 1 cm 부위에서 측정합니다.',settings:'접근법(경복부/경질)과 표본 위치를 기록하고 혈류에 빔을 정렬합니다. 좌우에서 안정적인 반복 파형을 확보합니다.',measure:'좌·우 PI와 평균 PI=(좌 PI+우 PI)/2를 기록하고 이완기 notch 여부를 확인합니다.',pitfall:'태반 내부 혈관·경질 자궁경부 길이 측정과 다릅니다. 분기·접근법·위치에 맞는 참고치와 위험 평가 알고리즘을 사용합니다.',images:['uta2'],refs:['isuog','first'],early:'11–13+6주 전자간증 선별 알고리즘에 포함될 수 있습니다. CRL·산모 특성과 해당 알고리즘을 함께 적용합니다.'}
};
const mapping={heart:['av'],lvot:['lv'],rvot:['rv'],threevpa:['rv'],threev:['arch'],vessels:['arch','duct'],aoarch:['arch'],ductarch:['duct'],bicaval:['ivc','dv'],abdomen:['dv'],cord:['ua'],head:['mca'],placenta:['uta'],cervix:['uta'],nt:['dv']};
export function dopplerFor(v){
 const keys=mapping[v.type];if(!keys)return null;
 const trimester=v.trimester||2;
 return {trimester,items:keys.map(key=>({...protocols[key],key,images:key==='uta'&&trimester===1?['uta1']:key==='arch'&&['threev','vessels'].includes(v.type)?['threevt',...protocols[key].images]:protocols[key].images,
 weeks:trimester===1?(protocols[key].early||'조기 정밀 심초음파의 적응증·가시성에 따라 평가하며, 아래 정량법은 중기 이후의 참고 내용입니다.'):(trimester===2?'2분기 · 검사 목적과 해당 주수의 참고치가 있는 경우':'3분기 · 성장·혈역학 또는 심장 질환의 적응증별 추적 평가')}))};
}
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function photo(key){const p=dopplerImages[key];const region=p.region;const style=region?`aspect-ratio:${region[2]}/${region[3]}`:'';
 const imageStyle=region?`position:absolute;width:${100*p.size[0]/region[2]}%;height:${100*p.size[1]/region[3]}%;left:${-100*region[0]/region[2]}%;top:${-100*region[1]/region[3]}%`:'';
 return `<figure class="doppler-photo"><div class="doppler-image" style="${style}"><img src="./${p.file}" alt="${esc(p.caption)}" loading="lazy" style="${imageStyle}"></div><figcaption><strong>${p.figure}</strong> · ${p.caption}<small>${p.age}</small><small>${p.credit} · <a href="${p.licenseUrl}" target="_blank" rel="noopener">${p.license}</a> · ${region?'해당 패널만 표시 · ':''}<a href="${p.source}" target="_blank" rel="noopener">원문·전체 그림 ↗</a></small></figcaption></figure>`;
}
export function renderDoppler(v){const d=dopplerFor(v);if(!d)return '';return `<section class="doppler-guide" aria-label="도플러 측정 세부 안내"><h3>도플러 측정 <small>${d.trimester}분기 · 컬러 / PW 별도 검사</small></h3><p>길이 계측과 구분하여 혈류의 위치·파형을 평가합니다. 컬러는 혈관과 방향을 찾는 데 사용하고, 유속·지수는 별도로 기록한 PW 스펙트럼에서 측정합니다.</p><p class="doppler-safety">${d.trimester===1?'1분기: 적응증이 있을 때만 도플러를 사용하며 TI ≤1.0, 가능한 짧은 노출을 지킵니다. 주수가 명시되지 않은 사진은 초기 정상 예시가 아닙니다.':'검사 중 TI·MI를 확인하고 ALARA 원칙을 적용합니다. 사진은 획득 방법 참고이며 선택한 주수의 정상값을 뜻하지 않습니다.'}</p>${d.items.map((p,i)=>`<details class="doppler-item" ${i===0?'open':''}><summary>${p.name}</summary><div class="doppler-body"><dl>${[['검사 목적',p.purpose],['주수·적용 범위',p.weeks],['추가 단면·정렬',p.plane],['표본용적 위치',p.gate],['입사각·장비 설정',p.settings],['파형·측정 항목',p.measure],['오류 방지',p.pitfall]].map(([k,val])=>`<dt>${k}</dt><dd>${esc(val)}</dd>`).join('')}</dl><div class="doppler-photos">${p.images.map(photo).join('')}</div><div class="measurement-sources">${[...new Set([...p.refs,'first'])].map(k=>`<a href="${refs[k][1]}" target="_blank" rel="noopener">${refs[k][0]} ↗</a>`).join('')}</div></div></details>`).join('')}</section>`;}
